import {head,note,section,link,action,submit,stats,field,area,select,hero,empty,chips,body,chart,fmt,duration,dateLabel,safe,icon} from './life-ui.js';
import {weightSummary,weightSummaryAt,sleepMinutes,shiftDate,routineDone} from './personal-state.js';
import {matchesSearch} from './mezo-state.js';
const kinds={note:'Gondolat',gratitude:'Hála',decision:'Döntés'};
export const latestSleep=s=>[...s.sleeps].sort((a,b)=>b.date.localeCompare(a.date))[0];
const trendCopy=w=>w.average===null?'Még nincs mérés ezen a héten.':`Az utóbbi ${w.count} mérés átlaga ${fmt(w.average)} kg. Egyetlen nap még nem mondja el az egész történetet.`;
export function mePage(s,p,v,id,ui,external,selectedDate=s.date){
 if(!v)return [()=>overview(s,external),()=>weight(s,ui,selectedDate),()=>sleep(s,selectedDate),()=>journal(s,ui,selectedDate)][p]();
 if(v==='weight-log')return weightForm(s,id);
 if(v==='weight-day'){const r=s.weights.find(x=>x.date===id);return r?head('MÉRÉSNAPLÓ · '+dateLabel(id),fmt(r.kg)+' kg','Egy pillanatkép a hosszabb ívben.','ring')+body(r.note||'Ehhez a méréshez nem írtál megjegyzést.')+action('Mérés pontosítása','me/1/weight-log/'+id)+link('bowl','Táplálkozás','A mai étkezésed és a kereted.','fuel/0')+link('moon','Alvás','A pihenésed története.','me/2'):missing();}
 if(v==='weight-context')return head('SÚLY · ÖSSZEFÜGGÉSEK','A mérleg csak egy jel.','A hosszabb ívet a napjaiddal együtt nézzük.','ring')+note(trendCopy(weightSummary(s)))+contextCards(s,external)+link('gem','Mit figyel Mezo?','Étkezés, regeneráció és edzés mintái.','mezo/0')+link('stack','A súlycélom','Saját irány és a kapcsolódó területek.','me/1/weight-goal');
 if(v==='weight-goal')return head('SAJÁT SÚLYCÉL','Egy irány. A te tempódban.','A demo célértéke nem írja át automatikusan az étrendet vagy az edzéstervedet.','ring')+hero('MEGADOTT CÉL',fmt(s.weightGoal),'kg','A napi mérésekhez viszonyítási pont.')+`<form data-life-form="weight-goal">${field('Saját célérték (kg)','target',s.weightGoal,'number','min="20" max="400" step="0.1" required')}${submit('Cél mentése')}</form>`+link('bowl','Étkezési keret','A mostani mintakeret külön marad.','fuel/0')+link('dumbbell','Terhelés','A teljesítmény is visszajelzés.','train/1');
 if(v==='sleep-log')return sleepForm(s,id);
 if(v==='sleep-night'){const r=s.sleeps.find(x=>x.date===id);return r?head('ÉJSZAKÁD · '+dateLabel(id),duration(sleepMinutes(r)),'A rögzített időpontok és a saját megélésed.','moon')+stats([[r.bed.slice(11),'lefekvés'],[r.wake.slice(11),'ébredés'],[r.quality+'/10','minőség']])+body(r.note||'Ehhez az éjszakához még nincs megjegyzés.')+note(`${r.awake} perc ébrenlétet vontunk le a két időpont közti időből. Ez saját becslés, nem műszeres mérés.`)+section('Amit még megjelöltél')+(r.factors.length?r.factors.map(f=>`<p class="lf-tag">${factors[f]||safe(f)}</p>`).join(''):note('Nem jelöltél körülményt. A hiányzó adatból nem következtetünk.'))+action('Éjszaka pontosítása','me/2/sleep-log/'+id)+link('gem','Az estéd átér a reggeledbe','Kapcsolódó minta a Mezo részben.','mezo/0/pattern/evening'):missing();}
 if(v==='sleep-rhythm')return head('ALVÁSRITMUS','A két nap közti híd.','Saját időzítésed és a naplózott éjszakák.','moon')+`<form data-life-form="sleep-goal">${field('Tervezett lefekvés','bed',s.bedGoal,'time','required')}${field('Saját alváscél (óra)','hours',s.sleepGoal/60,'number','min="1" max="16" step="0.25" required')}${submit('Ritmus mentése')}</form>`+note('Ezek saját tervezési pontok. Nem személyre szabott egészségügyi ajánlások és nem állítanak be valódi ébresztőt.')+link('ring','Esti rutin','Egy tartható átmenet a pihenésbe.','nap/2/chain/este')+link('moon','Éjszakai felület','Csendes, sötét nézet.','me/2/night')+link('gem','Étkezés és alvás','A megfigyelés és a bizonyíték külön.','mezo/0/pattern/evening');
 if(v==='sleep-context')return head('PIHENÉS · KERESZTHATÁSOK','Ugyanaz a test. Többféle nap.','Ezek kapcsolódási pontok, nem ok-okozati ítéletek.','moon')+contextCards(s,external)+link('gem','Röplabda × gym','Mit figyelünk a vállterhelés mellett?','mezo/0/pattern/load')+link('chat','Beszéljük át a mai napot','Az alvásod már a demókontextus része.','nap/1');
 if(v==='night')return `<div class="lf-night"><div class="lf-night-moon">${icon('moon')}</div><span class="overline">MOST MÁR RÁÉR</span><h1>Jó pihenést,<br>${safe(s.profile.name)}.</h1><p>Nem kell már semmit teljesítened.</p><strong>${s.bedGoal}</strong><small>a saját lefekvési terved</small>${action('Vissza az alváshoz','me/2',true)}<p class="lf-footer">Csendes demónézet. Nem indít alvásmérést vagy ébresztőt.</p></div>`;
 if(v==='entry-edit'&&id==='day-close')return head('NAPZÁRÁS','Az esti gondolataid egy helyen.','A pontosítást a napzárásban őrizzük meg.','moon')+action('Napzárás pontosítása','nap/3/close-edit');
 if(v==='entry-new'||v==='entry-edit')return entryForm(s,v==='entry-edit'?id:'',ui.entryKind,ui.journalDraft,v==='entry-new'&&id?id:selectedDate);
 if(v==='entry'){const e=s.entries.find(x=>x.id===id);return e?head(kinds[e.kind].toUpperCase()+' · '+dateLabel(e.date),e.kind==='decision'?'Egy döntés története.':e.kind==='gratitude'?'Amit jó megőrizni.':'A saját szavaiddal.','Ez a te bejegyzésed.','book')+body(e.text)+(e.kind==='decision'?section('Hogyan alakult?')+(e.review?body(e.review):note('Még nincs visszatekintés. Tervezett nap: '+dateLabel(e.due)))+`<form data-life-form="decision-review" data-id="${id}">${area('Utólag így látom','text',e.review||'')}${submit(e.review?'Visszatekintés pontosítása':'Visszatekintés mentése')}</form>`:'')+action('Bejegyzés szerkesztése',id==='day-close'?'nap/3/close-edit':'me/3/entry-edit/'+id)+`<button class="lf-action secondary" data-life-archive="${id}" data-value="${!e.archived}">${e.archived?'Visszaállítom':'Archívumba teszem'}</button>`+note(e.archived?'Ez a bejegyzés az archívumban van. Bármikor visszaállíthatod.':'A bejegyzés megőrzése nem változtatja tényállítássá a megélésedet.')+link('stack','Mezo emlékei','A demó memóriája külön mintagyűjtemény.','mezo/3/memory'):missing();}
 if(v==='goals')return head('SAJÁT IRÁNYAIM','Amiért csinálod.','Nem csak egy célérték. A miértje is a tiéd.','gem')+s.goals.map(g=>link('gem',safe(g.title),g.status==='active'?safe(g.step):'Szüneteltetve','me/0/goal/'+g.id)).join('')+action('Új saját cél','me/0/goal-new')+link('ring','Súlycél','A testtömegedhez tartozó irány.','me/1/weight-goal');
 if(v==='goal-new')return goalForm(s);
 if(v==='goal'){const g=s.goals.find(g=>g.id===id);return g?head('CÉL · '+(g.status==='active'?'AKTÍV':'SZÜNETEL'),safe(g.title),'Az irányt te alakítod.','gem')+section('Miért fontos?')+body(g.why)+section('A következő lépés')+body(g.step)+`<button class="lf-action secondary" data-life-goal="${id}">${g.status==='active'?'Most szüneteltetem':'Újra folytatom'}</button>`+goalForm(s,g)+link('ring','Beépítem a rutinomba','Egy kicsi, tartható lépés.','nap/2/new'):missing();}
 if(v==='profile')return head('SAJÁT PROFIL','Ahogy te mondanád.','A demóban minden itt megadott adat helyben marad.','person')+`<form data-life-form="profile">${field('Megszólítás','name',s.profile.name,'text','maxlength="40" required')}${field('Magasság (cm)','height',s.profile.height,'number','min="80" max="250" required')}${area('Egy mondat magadról','bio',s.profile.bio)}${submit('Profil mentése')}</form>`+link('person','Emberek','Akik részei a napjaidnak.','me/0/people')+link('stack','Beállítások','A demó megjelenése és emlékeztető-preferenciája.','me/0/settings');
 if(v==='settings')return head('SAJÁT BEÁLLÍTÁSOK','Úgy legyen jó neked.','A megjelenés kipróbálható, az emlékeztetők itt csak preferenciák.','stack')+`<button class="mz-toggle" data-life-setting="quiet" aria-pressed="${s.settings.quiet}"><span><strong>Nyugodtabb kártyák</strong><small>A hozzáadott dekoratív mozgások kikapcsolása.</small></span><b>${s.settings.quiet?'BE':'KI'}</b></button><button class="mz-toggle" data-life-setting="reminders" aria-pressed="${s.settings.reminders}"><span><strong>Szeretnék emlékeztetőt</strong><small>Demópreferencia; nem kér rendszerengedélyt és nem küld értesítést.</small></span><b>${s.settings.reminders?'BE':'KI'}</b></button>`+link('chat','Így beszélj velem','Mezo kommunikációs beállítása egy helyen.','mezo/3/tone')+link('stack','A demó adatai','Mi mentődik és mi csak látványterv?','me/0/data');
 if(v==='data')return head('A DEMÓ ADATAI','Átlátható mintavilág.','Itt tudod kipróbálni a működést.','stack')+body('A mérések, bejegyzések és visszajelzések csak ennek a nyitott lapnak a memóriájában élnek. Az újratöltés visszaállítja a mintanapot.\nNincs adatbázis, valódi AI-elemzés, hangfelvétel vagy értesítés. A szövegek és egészségi értékek nem rólad levont következtetések.\nAz edzés és az étkezés már korábban kidolgozott demófolyamata közös belépőkből érhető el. A Mezo mintái külön, előre megírt példák maradnak.');
 if(v==='people')return head('EMBEREK','Akikkel összeér a napod.','Kapcsolatok, említések és saját jegyzetek.','person')+s.people.map(x=>link('person',safe(x.name),x.role,'me/0/person/'+x.id)).join('')+note('Ezek kitalált mintaszereplők. Nincs személyekről automatikus értékelés.');
 if(v==='person'){const x=s.people.find(x=>x.id===id);return x?head('A SAJÁT KÖRÖD',safe(x.name),x.role,'person')+body(x.note)+section('Közös pillanatok')+x.mentions.map(t=>`<div class="lf-timeline-item">${safe(t)}</div>`).join('')+`<form data-life-form="person-note" data-id="${id}">${area('Egy új említés','text','','Mi történt köztetek?')}${submit('Megőrzöm a demóban')}</form>`+link('book','Írok róla a naplóba','A saját megélésednek van helye.','me/3/entry-new'):missing();}
 if(v==='week')return head('AZ UTÓBBI HÉT','Az egész képet nézd.','Hét napnyi minta, a saját naplózásaiddal.','ring')+contextCards(s,external)+section('Amit érdemes továbbvinni')+body('A hét ritmusában együtt volt jelen a gym és a röplabda. A regenerációhoz az alvásnapló ad saját visszajelzést.\nA hiányzó napokat nem pótoljuk kitalált értékekkel. Egy súlyingadozást nem értelmezünk önmagában sikernek vagy kudarcnak.')+link('gem','Felfedezések','Az összefüggések vizsgálata ott él.','mezo/0')+link('book','A hét saját története','A leírt gondolataid.','me/3');
 return missing();
}
function overview(s,e){const w=weightSummary(s),sl=latestSleep(s);return `<div class="lf-intro"><span class="overline">${safe(s.profile.name.toUpperCase())} · A SAJÁT VILÁGOD</span><p>${safe(s.profile.bio)}</p></div>`+stats([[fmt(w.average)+' kg','7 nap mért átlaga'],[sl?duration(sleepMinutes(sl)):'—','utolsó éjszaka'],[s.goals.filter(g=>g.status==='active').length,'saját irány']])+link('gem','Ami most fontos nekem',s.goals.filter(g=>g.status==='active').map(g=>safe(g.title)).join(' · '),'me/0/goals')+section('Ugyanannak a történetnek a részei')+`<div class="lf-pair">${link('ring','Súly',w.latest?fmt(w.latest.kg)+' kg · legutóbb':'Még nincs mérés','me/1')}${link('moon','Alvás',sl?sl.quality+'/10 · saját minőség':'Még nincs éjszaka','me/2')}</div>`+link('book','A saját szavaim',s.entries.filter(x=>!x.archived).length+' megőrzött bejegyzés','me/3')+link('ring','Heti összkép','Súly, pihenés, étkezés és mozgás együtt.','me/0/week')+section('Ami körülvesz')+link('person','Emberek','Akikkel megosztod a napjaidat.','me/0/people')+link('person','Profil és beállítások','Megszólítás, saját adatok és preferenciák.','me/0/profile');}
function contextCards(s,e){const w=weightSummary(s),sl=latestSleep(s);return `<div class="lf-context-grid">${link('ring','Súly',w.average===null?'Nincs heti mérés':fmt(w.average)+' kg · 7 nap átlaga','me/1')}${link('moon','Alvás',sl?duration(sleepMinutes(sl))+' · '+sl.quality+'/10':'Nincs naplózott éjszaka','me/2')}${link('bowl','Étkezés',fmt(e.food.kcal,0)+' kcal · ma rögzítve','fuel/0')}${link('dumbbell','Edzés',e.workout.complete?'Mai gym lezárva':'Mai gym még előtted / folyamatban','train/1')}</div>`+note('A kártyák a demó aktuális naplóit mutatják. Az együttjárásból még nem következik, hogy az egyik változás okozta a másikat.');}
function weight(s,ui,date){const w=weightSummaryAt(s,date),selected=s.weights.find(r=>r.date===date),rows=[...s.weights].filter(r=>r.date<=date&&r.date>=shiftDate(date,-Number(ui.weightPeriod)+1)).sort((a,b)=>a.date.localeCompare(b.date)),history=[...s.weights].filter(r=>r.date<=date).sort((a,b)=>b.date.localeCompare(a.date));return head('SÚLY','Ennek a napnak a pillanatképe.','Lapozz a napok között; a trend követi a kiválasztott pontot.','ring')+(selected?hero('NAPLÓZOTT MÉRÉS',fmt(selected.kg),'kg',selected.note||'Saját mérés ezen a napon.'):empty('Ezen a napon nincs mérés.','A hiányzó napot üresen hagyjuk; nem másoljuk át a legutóbbi értéket.','me/1/weight-log/'+date,'Mérést rögzítek'))+(selected?action('Mérés pontosítása','me/1/weight-log/'+date):'')+stats([[fmt(w.average),'eddigi 7 nap · kg'],[w.average!=null&&w.previous!=null?fmt(w.average-w.previous):'—','előző héthez · kg'],[fmt(s.weightGoal),'saját cél · kg']])+section('Az ív eddig')+chips('weightPeriod',[['7','7 nap'],['14','14 nap'],['30','30 nap']],ui.weightPeriod)+chart(rows,'kg','kg')+(ui.weightPeriod==='30'?note('A mintavilágban 14 napnyi súlyadat van; a hiányzó napokat nem töltjük ki.'): '')+link('chat','Mit érdemes együtt nézni?','Étrend, alvás és teljesítmény.','me/1/weight-context')+link('gem','Súlycélom',fmt(s.weightGoal)+' kg · módosítható saját irány','me/1/weight-goal')+`<details class="lf-history"><summary>Méréselőzmények <span>${history.length} mérés</span></summary>${history.map(r=>link('ring',fmt(r.kg)+' kg',dateLabel(r.date)+(r.note?' · '+safe(r.note):''),'me/1/weight-day/'+r.date)).join('')}</details>`;}
function weightForm(s,id){const date=id||s.date,r=s.weights.find(r=>r.date===date);return head('SÚLY · '+(r?'PONTOSÍTÁS':'ÚJ MÉRÉS'),'Egy pillanatkép.','Azonos napra mentve a korábbi mérésedet pontosítod.','ring')+`<form data-life-form="weight">${field('Mérés napja','date',r?.date||date,'date',`max="${s.date}" required ${id?'readonly':''}`)}${field('Súly (kg)','kg',r?.kg||'','number','min="20" max="400" step="0.1" required placeholder="81,4"')}${area('Megjegyzés','note',r?.note||'','Pl. reggel, étkezés előtt')}${submit(r?'Mérés pontosítása':'Mérés mentése')}</form>`+action('Mégse, vissza a súlyhoz','me/1',true);}
function sleep(s,date){const selected=s.sleeps.find(r=>r.date===date),rows=[...s.sleeps].filter(r=>r.date<=date).sort((a,b)=>a.date.localeCompare(b.date)),recent=rows.slice(-7),avg=recent.length?recent.reduce((n,r)=>n+sleepMinutes(r),0)/recent.length:null,history=[...rows].reverse();return head('ALVÁS','Az erre a napra virradó éjszaka.','A dátum mindig az ébredés napját jelöli.','moon')+(selected?hero('ERRE A NAPRA VIRRADÓAN',Math.floor(sleepMinutes(selected)/60),'óra '+Math.round(sleepMinutes(selected)%60)+' perc','Minőség '+selected.quality+'/10 · saját visszajelzés','moon'):empty('Ehhez a reggelhez nincs alvásnapló.','A hiányzó éjszakából nem becsülünk időtartamot.','me/2/sleep-log/'+date,'Éjszakát rögzítek'))+(selected?action('Éjszaka pontosítása','me/2/sleep-log/'+date):'')+stats([[avg===null?'—':duration(Math.round(avg)),recent.length+' éjszaka átlaga'],[duration(s.sleepGoal),'saját cél']])+chart(recent.map(r=>({date:r.date,hours:sleepMinutes(r)/60})),'hours','óra')+link('moon','A saját alvásritmusom',s.bedGoal+' · tervezett lefekvés','me/2/sleep-rhythm')+link('bolt','Pihenés és terhelés','A napjaid nem külön rendszerek.','me/2/sleep-context')+`<details class="lf-history"><summary>Alváselőzmények <span>${history.length} éjszaka</span></summary>${history.map(r=>link('moon',duration(sleepMinutes(r)),dateLabel(r.date)+' · minőség '+r.quality+'/10','me/2/sleep-night/'+r.date)).join('')}</details>`;}
const factors={'late-meal':'Késői étkezés',training:'Esti edzés',stress:'Sűrű nap',caffeine:'Késői koffein',calm:'Nyugodt este'};
function sleepForm(s,id){const date=id||s.date,r=s.sleeps.find(r=>r.date===date);return head('ALVÁS · SAJÁT NAPLÓ','Hogy telt az éjszakád?','A dátum az ébredés napja. A két időpontot külön is pontosíthatod.','moon')+`<form data-life-form="sleep">${field('Ébredés napja','date',r?.date||date,'date',`max="${s.date}" required ${id?'readonly':''}`)}${field('Lefekvés dátuma és ideje','bed',r?.bed||shiftDate(date,-1)+'T23:15','datetime-local','required')}${field('Ébredés dátuma és ideje','wake',r?.wake||date+'T07:00','datetime-local','required')}<div class="lf-form-pair">${field('Ébren töltött perc','awake',r?.awake??0,'number','min="0" max="1440" required')}${field('Minőség · 1–10','quality',r?.quality??7,'number','min="1" max="10" required')}</div><fieldset class="lf-checks"><legend>Mi volt még jelen?</legend>${Object.entries(factors).map(([v,l])=>`<label><input type="checkbox" name="factors" value="${v}" ${r?.factors.includes(v)?'checked':''}>${l}</label>`).join('')}</fieldset>${area('Saját megjegyzés','note',r?.note||'','Ami a számokból nem látszik…')}${submit('Éjszaka mentése')}</form>`+action('Mégse, vissza az alváshoz','me/2',true);}
export function journalRows(s,ui){const rows=s.entries.filter(e=>ui.journalFilter==='archive'?e.archived:!e.archived&&(ui.journalFilter==='all'||e.kind===ui.journalFilter)).filter(e=>matchesSearch(e.text,ui.journalQuery)).sort((a,b)=>b.date.localeCompare(a.date));return rows.length?rows.map(e=>`<button class="lf-journal-card" data-life="me/3/entry/${e.id}"><span>${kinds[e.kind]} · ${dateLabel(e.date)} ${e.review?'· visszanézve':''}</span><p>${safe(e.text.slice(0,150))}${e.text.length>150?'…':''}</p><b>Megnyitom ↗</b></button>`).join(''):empty('Most nincs ilyen bejegyzés.','Próbálj másik szűrőt vagy írj egy új gondolatot.','me/3/entry-new','Írok egy gondolatot');}
function journal(s,ui,date){const today=s.entries.filter(e=>e.date===date&&!e.archived).sort((a,b)=>a.id.localeCompare(b.id));return head('NAPLÓ','Ennek a napnak a saját szavai.','Lapozz a napok között; a keresés külön marad.','book')+action('Új bejegyzés erre a napra','me/3/entry-new/'+date)+link('chat','Inkább beszélgetnék','Mezo a mai nap kontextusából indul.','nap/1')+stats([[today.length,'bejegyzés ezen a napon'],[today.filter(e=>e.kind==='decision'&&!e.review).length,'nyitott döntés']])+section('Ezen a napon')+(today.length?today.map(e=>`<button class="lf-journal-card" data-life="me/3/entry/${e.id}"><span>${kinds[e.kind]} ${e.review?'· visszanézve':''}</span><p>${safe(e.text.slice(0,150))}${e.text.length>150?'…':''}</p><b>Megnyitom ↗</b></button>`).join(''):empty('Ezen a napon még nincs bejegyzés.','A csend is része lehet a történetnek.','me/3/entry-new/'+date,'Írok erre a napra'))+`<details class="lf-history"><summary>Keresés és archívum <span>${s.entries.filter(e=>!e.archived).length} bejegyzés</span></summary>${chips('journalFilter',[['all','Mind'],['note','Gondolat'],['gratitude','Hála'],['decision','Döntés'],['archive','Archívum']],ui.journalFilter)}<label class="lf-field">Keresés a naplóban<input type="search" data-life-search="journal" value="${safe(ui.journalQuery)}" placeholder="Pl. röplabda vagy nyugodt"></label><div id="life-journal-results">${journalRows(s,ui)}</div></details>`;}
function entryForm(s,id,kind,draft,date=s.date){const e=id?s.entries.find(x=>x.id===id):null;if(id&&!e)return missing();const k=e?.kind||kind;return head(kinds[k].toUpperCase()+' · '+(e?'SZERKESZTÉS':'ÚJ BEJEGYZÉS'),k==='decision'?'Mi mellett döntöttél?':k==='gratitude'?'Miért vagy ma hálás?':'Mi jár a fejedben?',k==='decision'?'A döntést és az utólagos visszatekintést külön őrizzük meg.':'Egyetlen mondat is elég.','book')+(!e?chips('entryKind',[['note','Gondolat'],['gratitude','Hála'],['decision','Döntés']],kind):'')+`<form data-life-form="entry" data-id="${id||''}" data-kind="${k}">${field('Bejegyzés napja','date',e?.date||date,'date',`max="${s.date}" required`)}${area(k==='gratitude'?'Amit ma jó megőrizni':k==='decision'?'A döntésem':'A gondolatom','text',e?.text||draft||'',k==='gratitude'?'Egy apró pillanat, egy ember, valami hétköznapi…':'Írd le úgy, ahogy most jön…')}${k==='decision'?field('Mikor néznél vissza rá?','due',e?.due||shiftDate(date,7),'date','required'):''}${submit(e?'Változtatások mentése':'Megőrzöm')}</form>`+action('Mégse, vissza a naplóhoz','me/3',true);}
function goalForm(s,g){return (!g?head('ÚJ SAJÁT IRÁNY','Mit szeretnél építeni?','Kezdj a miérttel, aztán legyen egy következő lépés.','gem'):'')+`<form data-life-form="goal" data-id="${g?.id||''}">${field('A cél neve','title',g?.title||'','text','maxlength="100" required')}${area('Miért fontos nekem?','why',g?.why||'')}${area('A következő tartható lépés','step',g?.step||'')}${submit(g?'Cél pontosítása':'Cél létrehozása')}</form>`;}
function missing(){return empty('Ez az oldal nem található.','Válassz egy területet az alsó menüből.','me/0','Vissza az áttekintéshez');}
